# Demo with corrected pydantic usage and other capabilities

from pydantic import BaseModel, field_validator

class User(BaseModel):
    name: str = "Anonymous"
    age: int

    @field_validator('age')
    @classmethod
    def validate_age(cls, v):
        if v < 0 or v > 120:
            raise ValueError('Age must be between 0 and 120')
        return v

user = User(name="Alice", age=30)
print(f"=== Pydantic Model Demo ===")
print(f"User model: {user}")

invalid_user = User(age=150)
try:
    user = invalid_user
except Exception as e:
    print(f"\nValidation error caught: {type(e).__name__}: {e}")

print("\n--- Completed ---")

